const rl = require("readline").createInterface({ input: process.stdin });
var iter = rl[Symbol.asyncIterator]();
const readline = async () => (await iter.next()).value;

void (async function () {
  const nums = (await readline()).split(",").map(Number);
  const target = parseInt(await readline());

  console.log(getResult(nums, target));
})();

function getResult(nums, target) {
  const n = nums.length;

  const preSum = new Array(n + 1).fill(0);
  for (let i = 1; i <= n; i++) {
    preSum[i] = preSum[i - 1] + nums[i - 1];
  }

  let maxLen = -1;
  for (let l = 0; l <= n - 1; l++) {
    for (let r = l + 1; r <= n; r++) {
      if (preSum[r] - preSum[l] == target) {
        maxLen = Math.max(maxLen, r - l);
      }
    }
  }

  return maxLen;
}

/* JavaScript Node ACM模式 控制台输入获取 */
const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

const lines = [];
rl.on("line", (line) => {
  lines.push(line);

  if (lines.length === 2) {
    const arr = lines[0].split(",").map(Number);
    const sum = parseInt(lines[1]);

    console.log(getMaxLen(arr, sum));

    lines.length = 0;
  }
});

function getMaxLen(arr, sum) {
  let ans = -1;

  if (sum <= 0) return ans;

  let l = 0;
  let r = 0;
  let n = arr.length;

  let total = arr[l];

  while (true) {
    if (total > sum) {
      l++;
      total -= arr[l - 1];
      if (l < n && r < l) {
        r = l;
        total += arr[r];
      }
    } else if (total < sum) {
      r++;
      if (r < n) total += arr[r];
      else break;
    } else {
      ans = Math.max(ans, r - l + 1);
      l++;
      r++;
      if (r < n) total += arr[r] - arr[l - 1];
      else break;
    }
  }

  return ans;
}

